 * billable role. Invitations and role changes are checked against this figure;
 * the stored counter that `usageFor()` reads tracks members alone.
 */
export async function seatsInUse(orgId: OrgId): Promise<number> {
  const active = await memberRepo.countActiveMembers(orgId);
  const pending = await invitationRepo.countPendingInvitations(orgId);
  return active + pending;
}

