      }),
    ).rejects.toThrow(/seats/);

    await expect(
      memberRepo.findMember(tenant.org.id, tenant.userIds.viewer),
    ).resolves.toMatchObject({ role: "viewer" });
  });

  // A billable member demoted to viewer frees a seat for a viewer to take.
  it("lets a viewer take the seat a billable member gives up", async () => {
    const tenant = await createTenant("member-seat-swap", "free");
    const admin = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    const viewer = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!admin || !viewer) throw new Error("fixture member missing");

    await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: admin.id,
      role: "viewer",
    });
    const promoted = await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: viewer.id,
      role: "member",
    });

    expect(promoted.role).toBe("member");
  });

  // Joins, role changes and removals move the stored seat counter by the same
  // rule a full recount applies, so the two always agree.
  it("keeps the seat counter equal to a full recount", async () => {
    const tenant = await createTenant("member-seat-counter", "growth");
    const admin = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    const member = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
    const viewer = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!admin || !member || !viewer) throw new Error("fixture member missing");

    const detach = registerUsageListeners();
    try {
      await usageRepo.recomputeUsage(tenant.org.id);

      await memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: viewer.id,
        role: "member",
      });
      await memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: admin.id,
        role: "viewer",
      });
      await memberService.removeMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: admin.id,
      });
      await memberService.removeMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: member.id,
      });

      const counted = await usageRepo.getUsage(tenant.org.id);
      const recounted = await usageRepo.recomputeUsage(tenant.org.id);

      // Owner and the former viewer, now a member, remain billable.
      expect(recounted.seatsUsed).toBe(2);
      expect(counted.seatsUsed).toBe(recounted.seatsUsed);
    } finally {
      detach();
    }
  });

  // A removed member is no longer a live row, so a second removal cannot
  // release the same seat again.
  it("refuses to remove an already removed member", async () => {
    const tenant = await createTenant("member-remove-twice", "growth");
    const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
    if (!target) throw new Error("fixture member missing");

    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: target.id,
    });

    await expect(
      memberService.removeMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: target.id,
      }),
    ).rejects.toThrow(/was not found/);
  });
});

